//! Replay bitmap-only cases generated by the supplied Python SPEC-v3 reference.
#[path = "support/bitmap_cases.rs"]
mod bitmap_cases;
#[test]
fn python_spec_v3_bitmap_corpus() {
    let cases: serde_json::Value =
        serde_json::from_str(include_str!("data/bitmap_reference.json")).unwrap();
    for case in cases["cases"].as_array().unwrap() {
        bitmap_cases::check(case);
    }
}
